#include <stdio.h>

int TestAndSet(int *old_ptr, int new) {
    int old = *old_ptr;  // Fetch the old value
    *old_ptr = new;     // Store the new value
    return old;         // Return the old value
}

int main() {
    int sharedVar = 0;  // Initialize a shared variable
    int result = TestAndSet(&sharedVar, 1);  // Call TestAndSet
    printf("Old value: %d\n", result);  // Output the result
    return 0;
}
